const API_BASE = '/api';

export async function apiRequest(endpoint, options = {}) {
  const token = localStorage.getItem('cnf_token');
  const headers = {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...(options.headers || {})
  };

  const config = {
    ...options,
    headers
  };

  if (options.body && typeof options.body === 'object' && !(options.body instanceof FormData)) {
    config.body = JSON.stringify(options.body);
  } else if (options.body instanceof FormData) {
    // Let the browser set multipart boundary
    delete headers['Content-Type'];
  }

  const response = await fetch(`${API_BASE}${endpoint}`, config);

  let data;
  try {
    data = await response.json();
  } catch (err) {
    data = null;
  }

  if (!response.ok) {
    const errorMsg = data?.error || response.statusText || 'An API error occurred.';
    const error = new Error(errorMsg);
    error.status = response.status;
    error.data = data;
    throw error;
  }

  return data;
}

export const api = {
  get: (endpoint) => apiRequest(endpoint, { method: 'GET' }),
  post: (endpoint, body) => apiRequest(endpoint, { method: 'POST', body }),
  put: (endpoint, body) => apiRequest(endpoint, { method: 'PUT', body }),
  delete: (endpoint) => apiRequest(endpoint, { method: 'DELETE' })
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../api/client';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('cnf_token');
    if (token) {
      api.get('/auth/me')
        .then((res) => {
          setUser(res.user);
        })
        .catch(() => {
          localStorage.removeItem('cnf_token');
          setUser(null);
        })
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, []);

  const login = async (email, password) => {
    const res = await api.post('/auth/login', { email, password });
    localStorage.setItem('cnf_token', res.token);
    setUser(res.user);
    return res.user;
  };

  const register = async (name, email, password, phone) => {
    const res = await api.post('/auth/register', { name, email, password, phone });
    localStorage.setItem('cnf_token', res.token);
    setUser(res.user);
    return res.user;
  };

  const logout = () => {
    localStorage.removeItem('cnf_token');
    setUser(null);
  };

  const refreshUser = async () => {
    try {
      const res = await api.get('/auth/me');
      setUser(res.user);
    } catch (e) {
      // ignore
    }
  };

  const addAddress = async (addressData) => {
    const res = await api.post('/auth/addresses', addressData);
    await refreshUser();
    return res.address;
  };

  const deleteAddress = async (id) => {
    await api.delete(`/auth/addresses/${id}`);
    await refreshUser();
  };

  const value = {
    user,
    loading,
    isAdmin: user?.role === 'ADMIN',
    login,
    register,
    logout,
    refreshUser,
    addAddress,
    deleteAddress
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../api/client';

const CartContext = createContext();

export function CartProvider({ children }) {
  const [items, setItems] = useState(() => {
    try {
      const saved = localStorage.getItem('cnf_cart');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  });

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [coupon, setCoupon] = useState(() => {
    try {
      const saved = localStorage.getItem('cnf_coupon');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [deliverySlot, setDeliverySlot] = useState('Standard (1:00 PM - 6:00 PM)');
  const [deliveryDate, setDeliveryDate] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() + 1); // Tomorrow by default
    return d.toISOString().split('T')[0];
  });

  useEffect(() => {
    localStorage.setItem('cnf_cart', JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    if (coupon) {
      localStorage.setItem('cnf_coupon', JSON.stringify(coupon));
    } else {
      localStorage.removeItem('cnf_coupon');
    }
  }, [coupon]);

  const addToCart = (productData) => {
    const cartId = `${productData.productId}_${productData.variantId || 'base'}_${Date.now()}`;
    const newItem = {
      cartId,
      productId: productData.productId,
      name: productData.name,
      price: productData.price,
      image: productData.image,
      variantId: productData.variantId || null,
      variantName: productData.variantName || null,
      quantity: productData.quantity || 1,
      customFlavor: productData.customFlavor || null,
      customInscription: productData.customInscription || null,
      customMessageCard: productData.customMessageCard || null,
      customPhotoUrl: productData.customPhotoUrl || null,
      isEggless: Boolean(productData.isEggless)
    };

    setItems((prev) => [...prev, newItem]);
    setIsCartOpen(true);
  };

  const removeFromCart = (cartId) => {
    setItems((prev) => prev.filter((item) => item.cartId !== cartId));
  };

  const updateQuantity = (cartId, quantity) => {
    if (quantity <= 0) {
      removeFromCart(cartId);
      return;
    }
    setItems((prev) =>
      prev.map((item) => (item.cartId === cartId ? { ...item, quantity } : item))
    );
  };

  const clearCart = () => {
    setItems([]);
    setCoupon(null);
    localStorage.removeItem('cnf_cart');
    localStorage.removeItem('cnf_coupon');
  };

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const calculateDeliveryFee = (slot, amount) => {
    if (!slot) return 5.0;
    const lower = slot.toLowerCase();
    if (lower.includes('midnight')) return 12.0;
    if (lower.includes('express')) return 8.0;
    if (amount >= 70.0) return 0.0;
    return 5.0;
  };

  const deliveryFee = items.length > 0 ? calculateDeliveryFee(deliverySlot, subtotal) : 0;

  const applyCoupon = async (code) => {
    const res = await api.post('/coupons/validate', { code, subtotal });
    if (res.valid) {
      setCoupon({
        code: res.code,
        discount: res.discount,
        discountType: res.discountType,
        discountValue: res.discountValue
      });
      return res;
    }
  };

  const removeCoupon = () => {
    setCoupon(null);
  };

  // Compute live discount
  let discountAmount = 0;
  if (coupon) {
    if (coupon.discountType === 'PERCENTAGE') {
      discountAmount = Math.round(((subtotal * coupon.discountValue) / 100) * 100) / 100;
    } else {
      discountAmount = Math.min(coupon.discountValue, subtotal);
    }
  }

  const total = Math.max(0, Math.round((subtotal + deliveryFee - discountAmount) * 100) / 100);
  const itemCount = items.reduce((sum, item) => sum + item.quantity, 0);

  const value = {
    items,
    addToCart,
    removeFromCart,
    updateQuantity,
    clearCart,
    isCartOpen,
    setIsCartOpen,
    coupon,
    applyCoupon,
    removeCoupon,
    discountAmount,
    deliveryDate,
    setDeliveryDate,
    deliverySlot,
    setDeliverySlot,
    deliveryFee,
    subtotal: Math.round(subtotal * 100) / 100,
    total,
    itemCount
  };

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
}

export function useCart() {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within a CartProvider');
  return context;
}

