  const handleSubmitReview = async (e) => {
    e.preventDefault();
    if (!newComment.trim()) return;
    setSubmittingReview(true);
    try {
      const res = await api.post('/reviews', {
        productId: product.id,
        rating: newRating,
        comment: newComment,
        userName: user?.name || reviewAuthor || 'Valued Guest'
