      await api.post('/admin/coupons', {
        code: newCouponCode,
        discountType: newCouponType,
        discountValue: parseFloat(newCouponVal),
        minOrderAmount: parseFloat(newCouponMin) || 0
      });
      alert('Coupon created successfully!');
      setNewCouponCode('');
      setNewCouponVal('');
      setNewCouponMin('');
      loadData();
